window.products.push({"id":643398,"name":"Botanica Emporium Abre Camino Road Opener Vision Candle | Spell Candle for Opening Up Opportunities | 7 Day Glass Spiritual Candle 8\" Tall","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71lBat9s1AL._AC_SL1500_.jpg","description":"Botanica Emporium is Your Premier Supplier of Quality Spiritual Remedies We source our products from the same manufacturers that have been supplying local Botanicas for decades. Our 7 Day Road Opener Candle is Perfect for Opening Up Opportunities in Life The 8\" tall glass jar makes our candle ideal for safe use at home and burning over long periods (NOTE: 7 Day Candles are more of a name than description of how long they burn but if you trim the wick and burn in 4 hour increments they can last 4-5 days on average) Bring the Botanica Experience to Your Front Door Botanicas have long been spiritual resource centers where customers could find their familiar old world cures and it is our pleasure to bring these traditions directly to you.","images":["https://m.media-amazon.com/images/I/71lBat9s1AL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Botanica Emporium","source_asin":"B084L4MX5F","category_path":"Home & Kitchen"},"sku":"BM-643398","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B084L4MX5F","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B084L4MX5F","price_pending":true,"merchant_ready":false});
